argv:
$ErrorActionPreference='Stop';
$f='E:\WebAIBridge\app\data\supervisor-watchdog.json';
if(!(Test-Path $f)){ [pscustomobject]@{exists=$false;path=$f} | ConvertTo-Json -Compress; exit 0 }
$j=Get-Content $f -Raw | ConvertFrom-Json;
[pscustomobject]@{
  exists=$true;
  path=$f;
  enabled=$j.enabled;
  mode=$j.mode;
  enforceHighMode=$j.enforceHighMode;
  highModeStrategy=$j.highModeStrategy;
  autoContinueEnabled=$j.autoContinueEnabled;
  allowAutonomousSend=$j.allowAutonomousSend;
  migrationEnabled=$j.migrationEnabled
} | ConvertTo-Json -Compress
